fn putmask(a: Vec<f32>, mask: Vec<bool>, values: Vec<f32>) -> Vec<f32> {
    let n = a.len();
    let m = values.len();
    let mut result = Vec::with_capacity(n);

    for i in 0..n {
        if mask[i] {
            // mask is true: take replacement value at position i % m
            result.push(values[i % m]);
        } else {
            // mask is false: keep original value
            result.push(a[i]);
        }
    }

    result
}